  (2^31 <= lbf < 2^32) ->
  stk asegs m lo (bv_unsigned sp) -> (lo <= bv_unsigned sp - 2304) -> (0 <= lo) -> (bv_unsigned sp < 2^63) ->
  mem_inv asegs m ->
